app.get('/broken', (req, res) => {
  throw new Error('BROKEN'); // Express catches this synchronously
});

// Error Handling Middleware MUST have 4 arguments
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ 
    error: 'Something broke!',
    message: err.message 
  });
});
